async () => {
  // B: identical navigation, with only the data attribute added
  document.documentElement.dataset.scrollBehavior = "smooth";
  const samples = [];
  window.scrollTo({ top: 2600, behavior: "instant" });
  await new Promise(r => setTimeout(r, 100));
  const startY = window.scrollY;
  document.querySelector('a[href="/lab/boundary"]').click();
  const t0 = performance.now();
  for (let i = 0; i < 8; i++) {
    await new Promise(r => setTimeout(r, 60));
    samples.push({ t: Math.round(performance.now() - t0), y: Math.round(window.scrollY) });
  }
  // C: and the anchor case — smooth must survive for hash scrolls.
  // Navigate via hash on this page: use the contents bar? Chapter pages have no
  // in-page anchor links, so test hash scroll directly against the demo anchor.
  const anchorSamples = [];
  const target = document.querySelector("section[id^='demo-']");
  location.hash = target ? target.id : "";
  const t1 = performance.now();
  for (let i = 0; i < 6; i++) {
    await new Promise(r => setTimeout(r, 50));
    anchorSamples.push({ t: Math.round(performance.now() - t1), y: Math.round(window.scrollY) });
  }
  return { startY, samples, endUrl: location.pathname, anchorSamples, hash: location.hash };
}

