  // On the landing page now: click a contents-bar anchor — the glide must survive.
  const link = document.querySelector('a[href="#demo-03"]');
  if (!link) return { error: "anchor link not found", path: location.pathname };
  const samples = [];
  link.click();
  const t0 = performance.now();
  for (let i = 0; i < 10; i++) {
    await new Promise(r => setTimeout(r, 70));
    samples.push({ t: Math.round(performance.now() - t0), y: Math.round(window.scrollY) });
  }
  return { path: location.pathname, hash: location.hash, samples };
}

